from 写入第二遍 import add
add('21_001',6,'16:9，董白正面头肩近景居画面中央，双马尾根部与高领肩线同框，双眼圆睁、嘴微张；固定眼高机位，脸后留浅云层。','董白先把眼睛睁到极圆，眼珠停在青所在的画外方向，嘴松成小圆口；第一问带着意外冲出来，肩膀尚未跟着放松。看青还站着，她吸了小半口气，眉尖略下收，后半句又端回指点别人的口吻；下巴抬了一点，眼睛仍没完全收回正常大小，嘴角也只轻轻合上。','两侧马尾之间为蓝灰云天与淡米灰薄尘，低层云纹缓慢横移。','段前仍以上方冷白云光为主，董白黑发与裙领留宽软冷反光，脸下侧由石面中性弱补光托住。','远处落石余响已稀，董白一口短吸气，双马尾根部轻擦衣领。',ja=['…何なの？そんな技があるなら、','最初から使えばよかったじゃない。'],tone='董白先惊问，再试着恢复指点人的从容；第二句带埋怨，眼神仍有未退的惊讶。',kind='mixed',phase='reaction',node={'叙事阶段':'董白惊讶青有此招式，尚未接触她'},meaning='董白圆眼小口的惊讶保留，两句由意外过渡到高傲的指点。',characters=['董白'],card={'opening':'她刚见到青压倒武士的力量，判断被打乱。','beats':['圆眼小口先惊问','吸气抬下巴，试着端回训人的口吻'],'coupling':'恢复姿态比语言慢一拍，惊讶仍留在眼中。','landing':'话说完时她仍远看青，尚未上前扶。'})
add('21_002',2,'16:9，从青背后看向董白的低机位中全景，青背腰和双膝占画面左侧近层，董白完整站姿缩在右后；镜头随青身体下沉稍降，落幅保留垂头与着地膝部。','青背脊忽然松掉，双膝向两侧屈开落向石面，肩膀随之猛低一截；两手垂在腿旁，指尖失去刚才的紧劲。她头先垂下，马尾却因惯性向左上扬出长弧，膝落地后才慢慢坠回；董白仍站在远处，刚端起的下巴停住，目光追着青下移。','灰绿石铺地面在二人之间展开，后层退成浅冷灰云雾面，近处石缝清楚。','上方冷白漫射照亮青银发与背肩，石面短影随下沉缩在双膝旁。','双膝落石的两下低短响，衣摆骤然折下，发尾掀起一记空风。',phase='process',node={'叙事阶段':'青失力跪落','青.状态':'屈膝跪下，仍清醒','青.支撑':'双膝与下垂身体','董白.位置':'远处站着看，未接触青'},meaning='用户确认青失力屈膝跪落；背后大姿态与董白远处站位保留。',motion='青垂直下沉，马尾反向上扬后落回；董白位置不变。',ground='双膝落在石面，未向前伏倒。',characters=['青','董白'])
add('21_003',4.5,'16:9，青正面头肩近景居画面左侧偏中，头微低、双眼半垂，嘴角与下沉肩线同框；固定略俯机位。','青跪着抬起一点脸，眉尖向上聚，双眼勉强留出窄缝；她先从气里漏出一小声笑，再张开嘴回应。说到该早点开大的话，她嘴角努力往上挑，肩头却随两次喘气颤动，脑袋又一点点低回去；长发已经落在胸前，她没再伸手拨开。','青发丝外侧是淡蓝灰云层和米灰薄尘，低处石面虚成灰绿软面。','冷白云光柔和覆盖额头，低垂眉眼下方有浅冷灰，发内层次稳定。','两口偏急的喘息，衣料随肩颤轻擦，跪姿压石细响。',ja=['…はは、ほんとだね。','最初から大技を出すべきだったよ。'],tone='青虚弱地笑着认同，后一句带自嘲，气息撑到句尾后明显落下。',kind='mixed',phase='reaction',node={'叙事阶段':'青跪姿中勉强笑着回应，继续失力'},meaning='青半垂眼、向上聚的眉、张嘴勉强笑与喘息保留，此时仍清醒能回应。',characters=['青'],card={'opening':'青想接住同伴的埋怨，身体却已透支。','beats':['勉强抬脸漏出一声笑','挑嘴角自嘲，肩随喘息颤','说完脑袋重新低下'],'coupling':'语言维持轻松，身体持续下沉，没有突然恢复力气。','landing':'笑意未能撑住姿态，接头垂与向前倒。'})
